DECLARE
V_COUNT INTEGER;
BEGIN
SELECT COUNT(TABLE_NAME) INTO V_COUNT from USER_TABLES where TABLE_NAME = '__EFMigrationsHistory';
IF V_COUNT = 0 THEN
Begin
BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"__EFMigrationsHistory" (
    "MigrationId" NVARCHAR2(150) NOT NULL,
    "ProductVersion" NVARCHAR2(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
)';
END;

End;

END IF;
EXCEPTION
WHEN OTHERS THEN
    IF(SQLCODE != -942)THEN
        RAISE;
    END IF;
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"TB_VITALIA_CART" (
    "CART_ID" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "USER_ID" NUMBER(19) NOT NULL,
    "STATUS" NVARCHAR2(20) NOT NULL,
    "CREATED_AT" TIMESTAMP(7) NOT NULL,
    "UPDATED_AT" TIMESTAMP(7) NOT NULL,
    CONSTRAINT "PK_TB_VITALIA_CART" PRIMARY KEY ("CART_ID")
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"TB_VITALIA_ORDERS" (
    "ORDER_ID" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "USER_ID" NUMBER(19) NOT NULL,
    "ORDER_DATE" TIMESTAMP(7) NOT NULL,
    "STATUS" NVARCHAR2(30) NOT NULL,
    "TOTAL_AMOUNT" DECIMAL(12,2) NOT NULL,
    CONSTRAINT "PK_TB_VITALIA_ORDERS" PRIMARY KEY ("ORDER_ID")
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"TB_VITALIA_PRODUCT_CATEGORY" (
    "CATEGORY_ID" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "NAME" NVARCHAR2(100) NOT NULL,
    "DESCRIPTION" NVARCHAR2(500),
    CONSTRAINT "PK_TB_VITALIA_PRODUCT_CATEGORY" PRIMARY KEY ("CATEGORY_ID")
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"TB_VITALIA_PRODUCT" (
    "PRODUCT_ID" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "NAME" NVARCHAR2(150) NOT NULL,
    "DESCRIPTION" NVARCHAR2(1000),
    "PRICE" DECIMAL(12,2) NOT NULL,
    "STOCK" NUMBER(10) NOT NULL,
    "STATUS" NVARCHAR2(20) NOT NULL,
    "CATEGORY_ID" NUMBER(19) NOT NULL,
    "CREATED_AT" TIMESTAMP(7) NOT NULL,
    "UPDATED_AT" TIMESTAMP(7) NOT NULL,
    CONSTRAINT "PK_TB_VITALIA_PRODUCT" PRIMARY KEY ("PRODUCT_ID"),
    CONSTRAINT "FK_TB_VITALIA_PRODUCT_TB_VITALIA_PRODUCT_CATEGORY_CATEGORY_ID" FOREIGN KEY ("CATEGORY_ID") REFERENCES "TB_VITALIA_PRODUCT_CATEGORY" ("CATEGORY_ID") ON DELETE CASCADE
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"TB_VITALIA_CART_ITEM" (
    "CART_ITEM_ID" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "CART_ID" NUMBER(19) NOT NULL,
    "PRODUCT_ID" NUMBER(19) NOT NULL,
    "QUANTITY" NUMBER(10) NOT NULL,
    "UNIT_PRICE" DECIMAL(12,2) NOT NULL,
    CONSTRAINT "PK_TB_VITALIA_CART_ITEM" PRIMARY KEY ("CART_ITEM_ID"),
    CONSTRAINT "FK_TB_VITALIA_CART_ITEM_TB_VITALIA_CART_CART_ID" FOREIGN KEY ("CART_ID") REFERENCES "TB_VITALIA_CART" ("CART_ID") ON DELETE CASCADE,
    CONSTRAINT "FK_TB_VITALIA_CART_ITEM_TB_VITALIA_PRODUCT_PRODUCT_ID" FOREIGN KEY ("PRODUCT_ID") REFERENCES "TB_VITALIA_PRODUCT" ("PRODUCT_ID") ON DELETE CASCADE
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"TB_VITALIA_ORDER_ITEM" (
    "ORDER_ITEM_ID" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "ORDER_ID" NUMBER(19) NOT NULL,
    "PRODUCT_ID" NUMBER(19) NOT NULL,
    "QUANTITY" NUMBER(10) NOT NULL,
    "UNIT_PRICE" DECIMAL(12,2) NOT NULL,
    "SUBTOTAL" DECIMAL(12,2) NOT NULL,
    CONSTRAINT "PK_TB_VITALIA_ORDER_ITEM" PRIMARY KEY ("ORDER_ITEM_ID"),
    CONSTRAINT "FK_TB_VITALIA_ORDER_ITEM_TB_VITALIA_ORDERS_ORDER_ID" FOREIGN KEY ("ORDER_ID") REFERENCES "TB_VITALIA_ORDERS" ("ORDER_ID") ON DELETE CASCADE,
    CONSTRAINT "FK_TB_VITALIA_ORDER_ITEM_TB_VITALIA_PRODUCT_PRODUCT_ID" FOREIGN KEY ("PRODUCT_ID") REFERENCES "TB_VITALIA_PRODUCT" ("PRODUCT_ID") ON DELETE CASCADE
)';
END;
/

CREATE UNIQUE INDEX "IX_TB_VITALIA_CART_ITEM_CART_ID_PRODUCT_ID" ON "TB_VITALIA_CART_ITEM" ("CART_ID", "PRODUCT_ID")
/

CREATE INDEX "IX_TB_VITALIA_CART_ITEM_PRODUCT_ID" ON "TB_VITALIA_CART_ITEM" ("PRODUCT_ID")
/

CREATE INDEX "IX_TB_VITALIA_ORDER_ITEM_ORDER_ID" ON "TB_VITALIA_ORDER_ITEM" ("ORDER_ID")
/

CREATE INDEX "IX_TB_VITALIA_ORDER_ITEM_PRODUCT_ID" ON "TB_VITALIA_ORDER_ITEM" ("PRODUCT_ID")
/

CREATE INDEX "IX_TB_VITALIA_PRODUCT_CATEGORY_ID" ON "TB_VITALIA_PRODUCT" ("CATEGORY_ID")
/

